// Return only future confirmed slots as ISO strings.
const now = Date.now();
const taken = [];
for (const item of $input.all()) {
  const s = item.json && item.json.start_at;
  if (!s) continue;
  const t = Date.parse(s);
  if (!Number.isNaN(t) && t > now) taken.push(new Date(t).toISOString());
}
return [{ json: { taken } }];

// Validate and normalise the booking request.
// Rules mirror the booking page: Mon-Fri, 09:00-17:00 Europe/Amsterdam, 30-minute slots,
// from tomorrow up to 28 days ahead.
const body = $input.first().json.body || {};
const str = v => (typeof v === 'string' ? v.trim() : '');

const name = str(body.name).slice(0, 120);
const email = str(body.email).toLowerCase().slice(0, 200);
const company = str(body.company).slice(0, 160);
const notes = str(body.notes).slice(0, 2000);
const lang = str(body.lang) === 'nl' ? 'nl' : 'en';
const honeypot = str(body.website);
const startAt = str(body.start_at);

const fail = (error) => [{ json: { valid: false, error } }];

if (honeypot) return fail('spam');
if (name.length < 2) return fail('name');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return fail('email');

const t = Date.parse(startAt);
if (Number.isNaN(t)) return fail('start_at');
const start = new Date(t);

// Interpret the instant in Europe/Amsterdam.
const fmt = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Amsterdam', weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false, year: 'numeric', month: '2-digit', day: '2-digit' });
const parts = Object.fromEntries(fmt.formatToParts(start).map(p => [p.type, p.value]));
const weekday = parts.weekday;
const hour = Number(parts.hour);
const minute = Number(parts.minute);

if (['Sat', 'Sun'].includes(weekday)) return fail('weekend');
if (minute !== 0 && minute !== 30) return fail('slot');
if (hour < 9 || hour > 16) return fail('hours');

// Fake "semi busy" pattern, mirrored from book.html (same hash, same rules; keep both in sync).
// Slots the page shows as taken are rejected here too, so nobody can book them by calling the webhook directly.
const BUSY_PATTERN = true;
const hashStr = s => { let h = 2166136261 >>> 0; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; } return h; };
const busySlotIndexes = key => {
  const out = new Set(); if (!BUSY_PATTERN) return out;
  const total = 16; const seed = hashStr(key);
  if (seed % 10 === 0) { for (let i = 0; i < total; i++) out.add(i); return out; }
  const blocks = 1 + (seed >>> 8) % 4;
  for (let b = 0; b < blocks; b++) { const h = hashStr(key + ':' + b); const st = h % total; const len = (h >>> 8) % 2 ? 2 : 1; for (let i = st; i < Math.min(total, st + len); i++) out.add(i); }
  return out;
};
const dayKey = `${parts.year}-${parts.month}-${parts.day}`;
const slotIndex = (hour - 9) * 2 + (minute === 30 ? 1 : 0);
if (busySlotIndexes(dayKey).has(slotIndex)) return fail('slot_taken');

const now = Date.now();
const dayMs = 86400000;
if (t < now + dayMs * 0.5) return fail('too_soon');
if (t > now + dayMs * 29) return fail('too_far');

const end = new Date(t + 30 * 60000);
const pretty = new Intl.DateTimeFormat(lang === 'nl' ? 'nl-NL' : 'en-GB', { timeZone: 'Europe/Amsterdam', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(start);
const time = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Amsterdam', hour: '2-digit', minute: '2-digit', hour12: false }).format(start);
const timeEnd = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Amsterdam', hour: '2-digit', minute: '2-digit', hour12: false }).format(end);

return [{ json: {
  valid: true,
  name, email, company, notes, lang,
  start_at: start.toISOString(),
  end_at: end.toISOString(),
  pretty_date: pretty,
  pretty_time: `${time} - ${timeEnd}`
} }];
